// ─────────────────────────────────────────────────────────────────────
// Node: Verify & Unwrap Intent Batch           Mode: Run Once for All Items
// Repo: n8n-multisource-intent-data-account-scorer · dhRobin Systems
// Envelope: { source: "bombora" | "6sense" | "g2", sent_at, signals: [...] }
// Signed with X-Intent-Timestamp (unix seconds) and
//   X-Intent-Signature: sha256=<hex HMAC-SHA256(secret, timestamp + "." + raw body)>
// using INTENT_WEBHOOK_SECRET_<SOURCE> (falls back to INTENT_WEBHOOK_SECRET).
// Constant-time compare, timestamp window outside sandbox, fails closed.
// ─────────────────────────────────────────────────────────────────────
const env = (key, fallback = '') => {
  try {
    const value = $env[key];
    return value === undefined || value === null || String(value).trim() === '' ? fallback : String(value).trim();
  } catch (error) {
    return fallback; // env access blocked -> safe defaults apply
  }
};
const flag = (key, fallback) => {
  const v = env(key, '').toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(v)) return true;
  if (['false', '0', 'no', 'off'].includes(v)) return false;
  return fallback; // unrecognised values keep the safe default
};
const num = (key, fallback) => {
  const raw = env(key, '');
  const n = Number(raw);
  return raw !== '' && Number.isFinite(n) ? n : fallback;
};
const csv = (key, fallback = '') => env(key, fallback).split(',').map((s) => s.trim()).filter(Boolean);

const helpers = this.helpers;
let crypto = null;
try { crypto = require('crypto'); } catch (error) { crypto = null; }
const SANDBOX_MODE = flag('SANDBOX_MODE', true);
const DRY_RUN = flag('DRY_RUN', true);
const TOLERANCE = Math.max(60, num('SIGNATURE_TOLERANCE_SECONDS', 300));
const SOURCES = ['bombora', '6sense', 'g2'];
const MAX_SIGNALS = Math.min(20000, Math.max(1, num('MAX_SIGNALS_PER_BATCH', 5000)));
const secretFor = (src) => env(`INTENT_WEBHOOK_SECRET_${src.toUpperCase()}`, '') || env('INTENT_WEBHOOK_SECRET', '') || (SANDBOX_MODE ? 'sandbox-fictional-intent-signing-secret' : '');
let runId; try { runId = 'ias_' + crypto.randomUUID(); } catch (e) { runId = 'ias_' + Date.now().toString(36); }
const run = { runId, startedAt: new Date().toISOString(), mode: SANDBOX_MODE ? 'sandbox' : DRY_RUN ? 'dry_run' : 'live', sandboxMode: SANDBOX_MODE, dryRun: DRY_RUN, origin: 'webhook' };
const items = $input.all();
const fx = SANDBOX_MODE ? ((items.find((i) => i.json.sandboxFixtures) || { json: {} }).json.sandboxFixtures || null) : null;
const sha = (s) => crypto.createHash('sha256').update(String(s)).digest();
const safeEqual = (a, b) => !!crypto && typeof a === 'string' && typeof b === 'string' && a.length > 0 && b.length > 0 && crypto.timingSafeEqual(sha(a), sha(b));
const out = [];
for (let index = 0; index < items.length; index++) {
  const item = items[index];
  const h = {};
  for (const [k, v] of Object.entries(item.json.headers || {})) h[String(k).toLowerCase()] = Array.isArray(v) ? String(v[0]) : String(v);
  let raw = null;
  if (item.binary && item.binary.data) { try { raw = (await helpers.getBinaryDataBuffer(index, 'data')).toString('utf8'); } catch (e) { raw = null; } }
  let body = item.json.body;
  if ((!body || (typeof body === 'object' && !Object.keys(body).length)) && raw) { try { body = JSON.parse(raw); } catch (e) { body = null; } }
  if (raw === null) raw = typeof body === 'string' ? body : JSON.stringify(body ?? {});
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = null; } }
  const b = body || {};
  const base = { run, sandboxFixtures: fx, deliveryRef: `delivery-${index + 1}` };
  const reject = (reason, source = null) => out.push({ json: { ...base, kind: 'rejected', reason, source } });
  if (!crypto) { reject('crypto_module_unavailable'); continue; }
  const source = String(b.source || '').toLowerCase().replace(/^sixsense$/, '6sense');
  if (!SOURCES.includes(source)) { reject('source_not_supported'); continue; }
  const secret = secretFor(source);
  if (!secret) { reject('webhook_secret_not_configured', source); continue; }
  const sigHeader = String(h['x-intent-signature'] || '').trim(); const ts = String(h['x-intent-timestamp'] || '').trim();
  if (!sigHeader || !ts) { reject('signature_header_missing', source); continue; }
  const sig = sigHeader.toLowerCase().startsWith('sha256=') ? sigHeader.slice(7) : sigHeader;
  if (!safeEqual(sig.toLowerCase(), crypto.createHmac('sha256', secret).update(`${ts}.${raw}`, 'utf8').digest('hex'))) { reject('signature_mismatch', source); continue; }
  if (!SANDBOX_MODE && (!Number.isFinite(Number(ts)) || Math.abs(Date.now() / 1000 - Number(ts)) > TOLERANCE)) { reject('timestamp_outside_tolerance', source); continue; }
  const signals = Array.isArray(b.signals) ? b.signals : [];
  if (!signals.length) { out.push({ json: { ...base, kind: 'ignored', reason: 'no_signals', source } }); continue; }
  out.push({ json: { ...base, kind: 'intent_batch', source, sentAt: b.sent_at || null, signals: signals.slice(0, MAX_SIGNALS), truncated: signals.length > MAX_SIGNALS } });
}
return out;

