const IP = env('INTENT_PROPERTY_PREFIX', 'intent_');
const P = {
  bomboraScore: `${IP}bombora_score`, bomboraDate: `${IP}bombora_date`, bomboraTopics: `${IP}bombora_topics`,
  sixScore: `${IP}6sense_score`, sixStage: `${IP}6sense_stage`, sixDate: `${IP}6sense_date`,
  g2Score: `${IP}g2_score`, g2Date: `${IP}g2_date`, g2Activity: `${IP}g2_activity`, g2Competitor: `${IP}g2_competitor_research`,
  intent: `${IP}score`, fit: `${IP}fit_score`, account: `${IP}account_score`, tier: `${IP}tier`, trend: `${IP}trend`, sources: `${IP}sources_active`,
  top: `${IP}top_signal`, review: `${IP}review_required`, reason: `${IP}review_reason`, scored: `${IP}last_scored`, history: `${IP}score_history`,
};
