const SOURCE_TRUST = jsonEnv('INTENT_SOURCE_WEIGHTS_JSON', { bombora: 0.85, '6sense': 1.0, g2: 0.9 });
const STAGE_SCORE = { target: 10, awareness: 30, consideration: 55, decision: 80, purchase: 95 };
