      return { type, n, date: dayOf(r.visit_date || r.date), w: G2_VISIT_WEIGHTS[type] ?? 0.3, product: r.product_name || '' }; })
      .map((v) => ({ ...v, points: 30 * v.w * (1 + Math.log(v.n)) })).sort((x, y) => y.points - x.points);
    const score = Math.min(100, Math.round(visits.slice(0, 4).reduce((s, v) => s + v.points, 0)));
